2	import { SANDBOX } from "../lib/sandbox";
3	import { connectionTarget, serverRootPassword } from "../lib/sftp";
4	import { withServerSsh, exec as sshExecOn } from "../lib/ssh-exec";
5	import { GAME_FAMILIES, type GameFamily } from "../lib/games";
6	import {
7	  judgeGameUpdate,
8	  parseGameUpdateOutput,
9	  updateCommand,
10	  updatesFromSteam,
11	} from "../lib/game-update-verify";
12	import type { Job } from "@prisma/client";
13	
14	/**
15	 * Game-server auto-update handlers.
16	 *
17	 * `gameUpdate` runs the per-family update over SSH against the server's private
18	 * IP (the worker can reach vmbr1) and PROVES the outcome before saying anything
19	 * to the customer. `gameUpdateSweep` finds RUNNING game servers with
20	 * `autoUpdate=true` and enqueues GAME_UPDATE jobs for them — safe to call
21	 * periodically (it de-dupes on in-flight jobs).
22	 *
23	 * The remote command used to end `; true` with every step `|| true`, so it could
24	 * not exit non-zero and this handler always fired *"The latest server update was
25	 * applied and the service was restarted."* — unattended, every 6 hours, whether
26	 * or not steamcmd existed, a unit matched, or the service came back. The command
27	 * builder, the output parser and the verdict now live in lib/game-update-verify.ts
28	 * where they are tested; SSH failure is still a failure, but a clean SSH exit is
29	 * no longer evidence of anything.
30	 *
31	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
32	 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
33	 */
34	
35	async function loadGameServer(serverId: string) {
36	  const server = await db.server.findUnique({
37	    where: { id: serverId },
38	    include: { osTemplate: true, dedicatedIp: true, node: true },
39	  });
40	  if (!server) throw new Error(`Server ${serverId} not found`);
41	  return server;
42	}
43	
44	async function notify(userId: string, title: string, body?: string, href?: string) {
45	  try {
46	    await db.notification.create({ data: { userId, title, body, href } });
47	  } catch (e) {
48	    console.error("[game-update] notify failed", e);
49	  }
50	}
51	
52	/**
53	 * Tell the customer once, not once per retry.
54	 *
55	 * The worker retries a failed job three times, and this one runs every six
56	 * hours; without this, a server whose steamcmd is missing would generate three
57	 * identical alarms per sweep, forever, and the customer would learn to ignore
58	 * them — which is the same outcome as not telling them.
59	 */
60	async function notifyFailureOnce(userId: string, serverId: string, title: string, body: string, href: string) {
61	  const since = new Date(Date.now() - 24 * 60 * 60_000);
62	  const dupe = await db.notification
63	    .findFirst({ where: { userId, title, createdAt: { gt: since } } })
64	    .catch(() => null);
65	  if (dupe) {
66	    console.error(`[game-update] ${serverId}: ${body} (customer already notified in the last 24h)`);
67	    return;
68	  }
69	  await notify(userId, title, body, href);
70	}
71	
72	/** Run the per-family update over SSH and verify the result. */
73	export async function gameUpdate(job: Job): Promise<void> {
74	  const server = await loadGameServer(job.serverId!);
75	  if (SANDBOX) {
76	    // No VM exists, so nothing can be proven. Say that, rather than simulating a
77	    // success message the production path is no longer willing to send.
78	    await notify(
79	      server.userId,
80	      `${server.osTemplate.name} auto-update simulated on ${server.hostname} (sandbox)`,
81	      "Sandbox only — no server was contacted, nothing was updated and nothing was restarted.",
82	      `/dashboard/servers/${server.id}`
83	    );
84	    return;
85	  }
86	  const family = server.osTemplate.family as GameFamily;
87	  if (!GAME_FAMILIES.includes(family)) {
88	    throw new Error(`game update: ${server.hostname} is not a game server`);
89	  }
90	  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
91	  const password = serverRootPassword(server);
92	  if (!connectionTarget(server) || !password) {
93	    throw new Error("game update: server has no IP/password yet");
94	  }
95	  const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
96	  const href = `/dashboard/servers/${server.id}`;
97	
98	  const remote = updateCommand(family);
99	  let stdout = "";
100	  let connError: string | null = null;
101	  try {
102	    // Host/port come from connectionTarget() (dedicated IP, or this server's
103	    // OWN node's public IP + its NAT-forwarded sshPort) — never the guest's
104	    // private bridge IP, which the worker has no route to for a non-primary node.
105	    const r = await withServerSsh(server, (conn) => sshExecOn(conn, remote, 600_000));
106	    stdout = r.stdout;
107	  } catch (e: any) {
108	    connError = scrub(String(e?.message ?? e));
109	  }
110	
111	  // A non-zero exit (or a connection failure) is meaningful, but the markers may
112	  // still have been printed before whatever went wrong — check for them
113	  // regardless of how we got here and let the verdict decide, rather than
114	  // discarding evidence. Absence of the end marker is ALWAYS treated as an
115	  // unproven run, exit code notwithstanding — a clean SSH exit is not evidence.
116	  if (connError || !/^NXGU:END$/m.test(stdout)) {
117	    const detail = connError ?? (scrub(stdout).trim() || "no output — the update did not run to completion");
118	    const reason = `game update failed: ${detail}`;
119	    await notifyFailureOnce(
120	      server.userId,
121	      server.id,
122	      `${server.osTemplate.name} auto-update FAILED on ${server.hostname}`,
123	      `We could not reach or run the update on your server, so nothing was updated: ${detail.slice(0, 300)}`,
124	      href
125	    );
126	    throw new Error(reason);
127	  }
128	
129	  const facts = parseGameUpdateOutput(scrub(stdout));
130	  const verdict = judgeGameUpdate({ family, hostname: server.hostname, facts });
131	
132	  if (!verdict.ok) {
133	    await notifyFailureOnce(
134	      server.userId,
135	      server.id,
136	      `${server.osTemplate.name} auto-update did not complete on ${server.hostname}`,
137	      verdict.reason,
138	      href
139	    );
140	    // Failing the job is the point: it puts the reason in Job.error and in the
141	    // admin job list instead of leaving a green tick over a dead server.
142	    throw new Error(`game update not verified: ${verdict.reason}`);
143	  }
144	
145	  // Only a real change is an event. This runs every 6 hours, so notifying on
146	  // every pass produced four "<game> updated on <host>" messages a day for a
147	  // server where nothing had been updated — the same erosion `notifyFailureOnce`
148	  // exists to prevent, and with a title that was not true.
149	  if (verdict.notify) await notify(server.userId, verdict.title, verdict.body, href);
150	  else console.log(`[game-update] ${server.hostname}: ${verdict.title} — ${verdict.body}`);
151	}
152	
153	/**
154	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
155	 * auto-update and has no job already in flight. Idempotent / safe to call on a
156	 * timer. Returns nothing; logs a summary.
157	 */
158	export async function gameUpdateSweep(): Promise<void> {
159	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
160	  const candidates = await db.server.findMany({
161	    where: {
162	      status: "RUNNING",
163	      autoUpdate: true,
164	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
165	    },
166	    select: { id: true, hostname: true, osTemplate: { select: { family: true } } },
167	  });
168	  if (candidates.length === 0) return;
169	
170	  let enqueued = 0;
171	  for (const s of candidates) {
172	    const inflight = await db.job.count({
173	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
174	    });
175	    if (inflight > 0) continue;
176	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
177	    enqueued++;
178	  }
179	  if (enqueued > 0) {
180	    const checkOnly = candidates.filter((s) => !updatesFromSteam(s.osTemplate.family as GameFamily)).length;
181	    console.log(
182	      `[game-update] sweep enqueued ${enqueued} job(s)` +
183	        (checkOnly > 0
184	          ? ` (${checkOnly} candidate(s) are families with no update source — those runs verify the unit is ` +
185	            `up and change nothing)`
186	          : "")
187	    );
188	  }
189	}
