import { db } from "../lib/db";

async function main() {
  const servers = await db.server.findMany({
    where: {
      OR: [
        { hostname: { contains: "suplosmp" } },
        { hostname: { contains: "projectzomboid-kc0kcr" } },
        { hostname: { contains: "cs2-dbhy4p" } },
      ],
    },
    include: { osTemplate: true, node: true, dedicatedIp: true },
  });

  for (const s of servers) {
    console.log("=".repeat(80));
    console.log(`hostname=${s.hostname} id=${s.id} status=${s.status} autoUpdate=${(s as any).autoUpdate}`);
    console.log(`family=${s.osTemplate?.family} osTemplate=${s.osTemplate?.name}`);
    console.log(`node=${s.node?.hostname ?? s.node?.id} dedicatedIp=${s.dedicatedIp?.address ?? null}`);
    const jobs = await db.job.findMany({
      where: { serverId: s.id, type: "GAME_UPDATE" },
      orderBy: { createdAt: "desc" },
      take: 10,
    });
    for (const j of jobs) {
      console.log(
        `  job=${j.id} status=${j.status} createdAt=${j.createdAt.toISOString()} updatedAt=${j.updatedAt?.toISOString?.() ?? ""}`
      );
      console.log(`    error=${JSON.stringify((j as any).error ?? null)}`);
    }
  }
  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

