import { db } from "../lib/db";
import { withServerSsh, exec } from "../lib/ssh-exec";

async function main() {
  const hostnames = ["suplosmp", "projectzomboid-kc0kcr"];
  const servers = await db.server.findMany({
    where: { hostname: { in: hostnames } },
    include: { osTemplate: true, node: true, dedicatedIp: true },
  });

  for (const s of servers) {
    console.log("=".repeat(90));
    console.log(`hostname=${s.hostname} family=${s.osTemplate.family} status=${s.status}`);
    const unit = s.osTemplate.family; // SERVICE_HINT maps 1:1 to family for these two
    const cmds = [
      `echo ---UNIT---; systemctl list-units --type=service --plain --no-legend | grep -i '${unit}' || echo NO_UNIT_MATCH`,
      `echo ---STATUS---; systemctl status ${unit} --no-pager -l 2>&1 | head -40`,
      `echo ---ISACTIVE---; systemctl is-active ${unit}; systemctl is-enabled ${unit}`,
      `echo ---JOURNAL---; journalctl -u ${unit} -n 60 --no-pager 2>&1`,
      `echo ---DOCKERPS---; docker ps -a 2>&1 | head -20`,
      `echo ---UPTIME---; uptime; echo ---DF---; df -h / 2>&1 | head -5; echo ---MEM---; free -h`,
    ];
    try {
      const r = await withServerSsh(s, (conn) => exec(conn, cmds.join("\n"), 30_000));
      console.log(r.stdout);
      if (r.stderr) console.log("STDERR:", r.stderr);
    } catch (e: any) {
      console.log("SSH ERROR:", e?.message ?? e);
    }
  }
  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

