/** Seconds we wait for the unit to come back before we stop claiming anything. */
export const RESTART_WAIT_TRIES = 30;
export const RESTART_WAIT_SLEEP_S = 2;

/**
 * Should `gameUpdateSweep` even enqueue a check for this candidate?
 *
 * `Server.status` is the VM's own power state, not the game service inside
 * it — `gamePower`'s own doc comment (worker/game-control.ts) is explicit
 * that the two are "genuinely different things". So a customer who presses
 * Stop on the dashboard (GAME_POWER "stop") leaves `status` at RUNNING
 * forever, and the sweep — which only ever looks at `status`+`autoUpdate` —
 * kept enqueueing a GAME_UPDATE job against it every cycle with no way to
 * know the service was off on purpose. Every one of those jobs then failed
 * with "your game server is NOT running", which is TRUE and also not news:
 * the customer did that themselves.
 *
 * Found live 2026-09-17: suplosmp (bedrock) generated a FAILED GAME_UPDATE
 * job on every single sweep for 28+ straight hours after its owner pressed
 * Stop and hadn't turned it back on — the same "customer would learn to
 * ignore it" erosion `notifyFailureOnce` already exists to prevent for
 * notifications, just unaddressed on the job-creation side.
 *
 * `gamePower` persists the post-action `systemctl is-active` result to
 * `Server.gameConfig._serviceState` (its own doc comment explains why: the
 * dashboard's status dot needed it). That is the one signal that distinguishes
 * "the customer turned this off" from "this crashed" — a crash is never
 * written here, only an explicit start/stop/restart action is. So only the
 * exact value "inactive" (a clean, completed stop) skips the sweep; anything
 * else — "failed" (a crash), "activating" (mid-restart), missing/stale — is
 * still checked normally, because those are precisely what this job exists
 * to catch.
 */
export function eligibleForUpdateSweep(gameConfig: unknown): boolean {
  const state = (gameConfig as Record<string, unknown> | null | undefined)?.["_serviceState"];
  return state !== "inactive";
}

