/* ------------------------------------------------------------------ *
 * 5. Sweep eligibility: a deliberately-stopped service is not a failure
 *
 * INCIDENT (found live 2026-09-17): `Server.status` is the VM's own power
 * state, not the game service inside it (see gamePower's doc comment in
 * worker/game-control.ts), so a customer who presses Stop on the dashboard
 * leaves `status` at RUNNING and the sweep — which only looks at
 * `status`+`autoUpdate` — kept enqueueing a GAME_UPDATE job against it every
 * cycle forever. suplosmp (bedrock) generated a FAILED job on every single
 * run for 28+ straight hours after its owner pressed Stop; the failure
 * message ("your game server is NOT running") was true and also not news.
 * `gamePower` persists the post-action state to `gameConfig._serviceState`;
 * `eligibleForUpdateSweep` is the one place that reads it back.
 * ------------------------------------------------------------------ */

test("eligibleForUpdateSweep: a clean customer-initiated stop is skipped", () => {
  assert.equal(eligibleForUpdateSweep({ _serviceState: "inactive" }), false);
});

test("eligibleForUpdateSweep: a crash ('failed') is still checked, not skipped", () => {
  assert.equal(eligibleForUpdateSweep({ _serviceState: "failed" }), true);
});

test("eligibleForUpdateSweep: mid-restart ('activating') is still checked", () => {
  assert.equal(eligibleForUpdateSweep({ _serviceState: "activating" }), true);
});

test("eligibleForUpdateSweep: no recorded state (never power-toggled) is still checked", () => {
  assert.equal(eligibleForUpdateSweep(null), true);
  assert.equal(eligibleForUpdateSweep(undefined), true);
  assert.equal(eligibleForUpdateSweep({}), true);
});

